"""生图 Broker —— 全框架唯一一个调用生图接口的地方。职责链条：    vault 取 key → provider 出图 → media_store 落盘换净链 → 返回 ImageRef插件只能拿到最后的 `ImageRef`（含无参数 URL），拿不到 key、endpoint、签名 URL。"""from __future__ import annotationsfrom typing import Anyfrom haiqbot.plugin_api import ImageProvider, ImageRef, MediaStore, ProviderError, get_loggerlog = get_logger(__name__)class ImageBroker:    def __init__(        self,        provider: ImageProvider,        media: MediaStore,        *,        default_size: str = "1024x1024",        plugin_id: str | None = None,    ) -> None:        self.provider = provider        self.media = media        self.default_size = default_size        # 谁提供的这个能力 —— 落进 media 表，面板「媒体」页才能按插件筛        self.plugin_id = plugin_id    async def generate(self, prompt: str, *, size: str | None = None) -> ImageRef:        data, mime = await self.provider.generate(prompt, size or self.default_size)        limit = int(getattr(self, "max_prompt", 0) or 0)        if limit and len(prompt) > limit:            raise ProviderError(f"提示词太长（{len(prompt)} 字 > 上限 {limit}），请精简后重试")        ref = await self.media.put(data, mime, plugin_id=self.plugin_id)        log.info(            "image_broker_done",            provider=getattr(self.provider, "name", "unknown"),            bytes=len(data),            media_id=ref.id,        )        return ImageRef(media_id=ref.id, url=ref.url, mime=mime, path=ref.path)    def describe(self) -> dict[str, Any]:        return {            "provider": getattr(self.provider, "name", "unknown"),            "default_size": self.default_size,            "public_base_url": self.media.base_url,        }